x.append(R(6479129,"झींगा और एवोकाडो टैको बाउल","पका हुआ झींगा एक आसान शॉर्टकट है, या आप बचा हुआ झींगा उपयोग कर सकते हैं और उसे रात भर फ्रिज में रख सकते हैं। अनानास और एवोकाडो इन आसान टैको बाउल में ताज़ा और चटकीला स्वाद जोड़ते हैं।","2","1 लेट्यूस बाउल + 4 औंस झींगा + लगभग 1/2 कप अनानास और एवोकाडो",
["1/2 पाउंड पूरी तरह पका हुआ झींगा (छिला, नस निकाला और पूँछ हटाई हुई)","1/4 कप सालसा","1/2 मध्यम एवोकाडो (छिला और छोटे टुकड़ों में कटा हुआ)","1 मध्यम टमाटर (छोटे टुकड़ों में कटा हुआ)","1/4 कप हरा प्याज (स्प्रिंग अनियन) (बारीक कटा हुआ)","1/4 कप ताज़ा अनानास (बारीक कटा हुआ)","1 बड़ा चम्मच जलापेनो मिर्च (कटी हुई, वैकल्पिक)","2 पत्ते बिब लेट्यूस","1/2 छोटा चम्मच चिली पाउडर","1/4 कप सादा नॉनफैट ग्रीक योगर्ट","2 बड़े चम्मच ताज़ा धनिया (वैकल्पिक)"],
["झींगा, एवोकाडो, टमाटर, स्प्रिंग अनियन और अनानास (और चाहें तो जलापेनो) मिलाएँ। बाउल बनाने के लिए हर लेट्यूस के सिर से बीच के कुछ पत्ते निकाल दें। झींगे के मिश्रण को लेट्यूस के सिरों में बाँट दें।","ग्रीक योगर्ट में चिली पाउडर मिलाएँ।","हर \"टैको\" बाउल के ऊपर ग्रीक योगर्ट का मिश्रण और सालसा डालें। चाहें तो ऊपर से कटा हुआ ताज़ा धनिया छिड़कें।"]))
x.append(R(6480132,"कैलिफ़ोर्निया खजूर और एकॉर्न स्क्वैश सलाद","कैलिफ़ोर्निया खजूर की मिठास अरुगुला के तीखेपन के साथ बहुत सुंदर मेल खाती है, और भारतीय मसाला मिश्रण गरम मसाला इस लुभावने साइड डिश में स्वाद की गहराई जोड़ता है। एकॉर्न स्क्वैश का छिलका रखने से भी व्यंजन में बनावट और फाइबर बढ़ता है। एकॉर्न स्क्वैश की जगह सर्दियों की अन्य किस्में, जैसे डेलिकाटा स्क्वैश, बेझिझक उपयोग करें।","6","2/3 कप",
["1 साबुत एकॉर्न स्क्वैश (1/2 इंच मोटे स्लाइस में कटा हुआ)","1 बड़ा चम्मच ऑलिव ऑयल","1 छोटा चम्मच कोशर नमक (बाँटकर उपयोग के लिए)","3/4 छोटा चम्मच गरम मसाला (बाँटकर उपयोग के लिए)","2 बड़े चम्मच ताज़ा निचोड़ा संतरे का रस","1 बड़ा चम्मच खुबानी का जैम (कम चीनी वाला)","1/4 छोटा चम्मच काली मिर्च","3/4 कप कैलिफ़ोर्निया खजूर (बीज निकाले हुए और चार टुकड़ों में कटे हुए)","5 कप अरुगुला","1/3 कप अपनी पसंद के भुने हुए मेवे (जैसे पिस्ता, पीकन, अखरोट या बादाम)"],
["ओवन को पहले से 425°F पर गरम करें और बेकिंग शीट पर फ़ॉइल या बेकिंग पेपर बिछाएँ।","एक बड़े कटोरे में स्क्वैश, तेल, 1/2 छोटा चम्मच नमक और 1/2 छोटा चम्मच गरम मसाला डालकर अच्छी तरह मिलाएँ। स्क्वैश को बेकिंग शीट पर एक परत में रखें और 20 मिनट भूनें, बीच में टुकड़ों को पलट दें।","उसी कटोरे में रस, जैम, पिसी काली मिर्च और बचा हुआ 1/2 छोटा चम्मच नमक और 1/4 छोटा चम्मच गरम मसाला डालें। अच्छी तरह फेंटें।","भुना हुआ स्क्वैश और खजूर कटोरे में डालकर मिलाएँ।","अरुगुला को एक बड़े सर्विंग बाउल या प्लेटर में रखें। स्क्वैश और खजूर डालें। ऊपर से भुने हुए मेवे डालें।"]))
x.append(R(6480190,"भुनी सब्ज़ियों का स्ट्राटा","यह अंडे पर आधारित मुख्य व्यंजन दिन के किसी भी समय के लिए बढ़िया है और बचा हुआ हिस्सा अगले दिन के लिए आसानी से साथ ले जाने वाला लंच बन सकता है।","8","स्ट्राटा का 1/8",
["5-6 स्प्रे नॉनस्टिक कुकिंग स्प्रे","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1 मध्यम शकरकंद (6 औंस, छिला और छोटे टुकड़ों में कटा हुआ)","1 मध्यम प्याज (छोटे टुकड़ों में कटा हुआ)","1 मध्यम लाल शिमला मिर्च (बीज निकाली और छोटे टुकड़ों में कटी हुई)","1/2 छोटा चम्मच स्पाइक सीज़निंग (बिना नमक वाली)","2 बड़े अंडे","4 बड़े एग व्हाइट","1 छोटा चम्मच सरसों (सूखी)","2 बड़े चम्मच ताज़ा सेज (कटा हुआ)","1/2 छोटा चम्मच काली मिर्च","8 स्लाइस होल व्हीट ब्रेड (प्रत्येक 1.5 औंस)","1/2 कप परमेसन चीज़ (कद्दूकस किया हुआ, बाँटकर उपयोग के लिए)"],
["ओवन को पहले से 375°F पर गरम करें। एक बड़ी बेकिंग शीट पर कुकिंग स्प्रे लगाएँ।","सारी सब्ज़ियों को आपस में मिलाएँ और बेकिंग शीट पर बराबर फैलाएँ। सब्ज़ियों पर 5-6 बार कुकिंग स्प्रे करें और बिना नमक वाली स्पाइक सीज़निंग डालें।","सब्ज़ियों को 30 मिनट भूनें, फिर थोड़ा ठंडा होने के लिए एक तरफ रख दें।","अंडे, एग व्हाइट, सूखी सरसों, सेज और काली मिर्च को आपस में फेंटें।","9x13 इंच के कैसरोल डिश पर कुकिंग स्प्रे लगाएँ। होल व्हीट ब्रेड के चार स्लाइस को टुकड़ों में तोड़कर कैसरोल डिश की तली में परत लगाएँ। ऊपर से आधी भुनी सब्ज़ियाँ और 1/4 कप परमेसन चीज़ डालें। आधा अंडे का मिश्रण ब्रेड, सब्ज़ियों और चीज़ पर डालें।","बची हुई टूटी ब्रेड, सब्ज़ियों, चीज़ और अंडे के मिश्रण के साथ परतें दोहराएँ। कैसरोल को स्पैचुला से दबाएँ ताकि सारी ब्रेड अंडे के मिश्रण में भीग जाए। स्ट्राटा को 15 मिनट कमरे के तापमान पर रखा रहने दें।","स्ट्राटा को 30 मिनट बेक करें।","परोसने के लिए, स्ट्राटा को लंबाई में बीच से काटें, फिर चौड़ाई में बीच से काटें। हर आधे हिस्से को चौड़ाई में फिर बीच से काटें ताकि 8 बराबर सर्विंग बन जाएँ।"]))
x.append(R(6481807,"अदरक वाला कद्दू बिस्क","यह मीठा और चटपटा सूप कद्दू, नाशपाती और ताज़े अदरक को एक मलाईदार सूप में मिलाता है जो ठंडे पतझड़ के दिन आपको गर्माहट देगा। आप सब कुछ स्लो-कुकर में डालकर पूरे दिन पकने दे सकते हैं, ताकि काम से घर लौटने पर रात का खाना तैयार हो। इस व्यंजन को पतझड़ थीम वाले सूप-और-सलाद कॉम्बो के लिए अरुगुला, नाशपाती, अखरोट और पेकोरिनो सलाद के साथ, या कुछ ज़्यादा भरपेट के लिए टैरागन हर्ब्ड चिकन और मशरूम के साथ परोसें।","6","1 कप सूप और 1 बड़ा चम्मच योगर्ट",
["1 (15 औंस) कैन कद्दू की प्यूरी","1 मध्यम सख़्त नाशपाती (छिली, बीज निकाली और कटी हुई)","1 1/2 कप प्याज (छोटे टुकड़ों में कटा हुआ)","1 (14.5 औंस) कैन कम सोडियम चिकन या वेजिटेबल ब्रॉथ","1/2 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच पिसा जायफल","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच लाल मिर्च पाउडर","2 कप फैट-फ्री हाफ-एंड-हाफ","1/4 कप ट्रांस-फैट-मुक्त मार्जरीन","1 1/2 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","1 बड़ा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","6 बड़े चम्मच सादा नॉनफैट ग्रीक योगर्ट"],
["3 1/2 से 4 क्वार्ट के स्लो कुकर पर कुकिंग स्प्रे लगाएँ। कद्दू, नाशपाती, प्याज, ब्रॉथ, जीरा, जायफल, नमक और लाल मिर्च स्लो कुकर में डालें। ढककर तेज़ आंच पर 3 1/2 घंटे, या धीमी आंच पर 7 घंटे, या प्याज नरम होने तक पकाएँ।","1-1 कप के हिस्सों में कद्दू के मिश्रण को ब्लेंडर में प्यूरी करें, ब्लेंड करते समय ढक्कन को कसकर बंद रखना न भूलें। मिश्रण को वापस स्लो कुकर में डालें, योगर्ट को छोड़कर बाकी सामग्री मिलाएँ। ढककर तेज़ आंच पर 30 मिनट और पकाएँ।","परोसते समय ऊपर से 1 बड़ा चम्मच योगर्ट डालें।"]))
x.append(R(6482949,"ग्रिल की हुई स्ट्रॉबेरी \"क्रीम\" पर बाल्समिक ग्लेज़ के साथ","क्रीम पर बाल्समिक ग्लेज़ के साथ ग्रिल की हुई स्ट्रॉबेरी की यह मधुमेह के अनुकूल रेसिपी निश्चित रूप से प्रभावित करेगी! मेपल सिरप या शहद जैसे प्राकृतिक स्वीटनर का उपयोग अतिरिक्त पोषक तत्व जोड़ता है। ग्रीक योगर्ट अतिरिक्त प्रोटीन देता है जो इस स्वादिष्ट मिठाई को खाने के बाद आपको तृप्त रखने में मदद करता है। अगर आप ग्लूटेन-मुक्त या शाकाहारी मीठा व्यंजन खोज रहे हैं, तो यह भी बढ़िया विकल्प है।","2","1/2 प्लेट (9 स्ट्रॉबेरी के आधे टुकड़े + 1/3 कप क्रीम)",
["2/3 कप सादा नॉनफैट ग्रीक योगर्ट","1 बड़ा चम्मच लाइट क्रीम चीज़ (कमरे के तापमान पर)","1/2 छोटा चम्मच शहद","9 बड़ी स्ट्रॉबेरी (डंठल निकाली और आधी कटी हुई)","2 छोटे चम्मच सूरजमुखी या एवोकाडो का तेल","1 बड़ा चम्मच बाल्समिक ग्लेज़ या बाल्समिक रिडक्शन सॉस*","2 छोटे चम्मच कटे हुए बादाम (पैन में भुने हुए या कच्चे)","1 बड़ा चम्मच बहुत छोटी ताज़ी तुलसी या पुदीने की पत्तियाँ"],
["एक मध्यम कटोरे में योगर्ट, न्यूशातेल और शहद को गाढ़ा और मलाईदार होने तक फेंटें। क्रीम को सर्विंग प्लेटर या बोर्ड पर फैलाएँ।","ग्रिल या ग्रिल पैन तैयार करके पहले से गरम करें। स्ट्रॉबेरी के आधे टुकड़ों के कटे हुए हिस्से पर तेल लगाएँ और सीधी मध्यम-तेज़ आंच पर कटा हिस्सा नीचे रखकर, गहरे ग्रिल निशान बनने तक, लगभग 4 मिनट ग्रिल करें।","स्ट्रॉबेरी को क्रीम पर सजाएँ। ऊपर से बाल्समिक ग्लेज़ डालें, बादाम और ताज़ी जड़ी-बूटियाँ छिड़कें, और परोसें।","*अपना बाल्समिक रिडक्शन सॉस बनाएँ: एक छोटे सॉस पैन में 1/4 कप बाल्समिक सिरका डालें, तेज़ आंच पर उबालें, फिर आंच को मध्यम करें और कुछ बार चलाते हुए तब तक पकाएँ जब तक वह बस चम्मच के पिछले हिस्से पर लिपटने न लगे (लगभग 1 1/2 बड़े चम्मच बनेगा), लगभग 5 मिनट। (ध्यान दें: बाल्समिक रिडक्शन ठंडा होने पर थोड़ा और गाढ़ा होता है।)"]))
x.append(R(6483037,"मिर्च और नींबू वाला ग्रिल्ड भुट्टा","इस मिर्च और नींबू वाले ग्रिल्ड भुट्टे के साथ टेक्स-मेक्स का आनंद लें। मैक्सिकन स्ट्रीट कॉर्न जैसा स्वाद देने वाली यह मधुमेह के अनुकूल रेसिपी स्वादिष्ट और पौष्टिक है।","4","1 भुट्टा",
["1 कप ताज़ा धनिया (कटा हुआ, सजावट के लिए)","1/4 कप पार्ट-स्किम मोत्ज़ारेला (सजावट के लिए)","1/8 छोटा चम्मच नमक","1 मध्यम नींबू (लाइम) (ज़ेस्ट और रस)","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1 छोटा चम्मच चिली पाउडर","1 साबुत नॉनस्टिक कुकिंग स्प्रे","4 मध्यम भुट्टे (छिलका उतारे हुए)"],
["ग्रिल को मध्यम-तेज़ आंच पर पहले से गरम करें।","एक छोटे कटोरे में ऑलिव ऑयल, चिली पाउडर, स्मोक्ड पेपरिका, नींबू का ज़ेस्ट, नींबू का रस और नमक फेंटें।","भुट्टों पर मैरिनेड लगाएँ, ध्यान रखें कि वह बराबर लग जाए।","भुट्टों को कम से कम 30 मिनट मैरिनेट होने दें।","मैरिनेट किए भुट्टों को पहले से गरम ग्रिल पर रखें। बीच-बीच में पलटते हुए लगभग 15 मिनट तक, जब तक भुट्टे हल्के जले और पक न जाएँ, ग्रिल करें।","ग्रिल किए भुट्टों को आंच से उतार लें।","भुट्टों को सर्विंग प्लेटर पर रखें और कोटिया चीज़ और ताज़ा कटा धनिया छिड़कें।"]))
x.append(R(6483274,"शीट पैन तोरई और लाल शिमला मिर्च \"स्टर-फ्राई\"","यह रेसिपी दिखने और स्वाद में स्टर-फ्राई जैसी लगती है, लेकिन इसे स्टोव पर पकाने के बजाय ओवन में भूना जाता है। बस सब कुछ मिलाएँ, शीट पैन पर फैलाएँ और बेक होने दें! यह जैसी है वैसी ही बढ़िया है, या आप कुछ और स्वाद जोड़ सकते हैं: कुरकुरेपन के लिए मूँगफली छिड़कें; तीखेपन के लिए हॉट सॉस डालें; जड़ी-बूटी के स्वाद के लिए ताज़ा धनिया डालें।","4","1 1/2 कप",
["2 मध्यम लाल शिमला मिर्च (1 इंच की पट्टियों में कटी हुई)","2 मध्यम तोरई (1/2 इंच मोटे गोल टुकड़ों में कटी हुई)","1 1/2 बड़े चम्मच भुना हुआ तिल का तेल","1 1/2 बड़े चम्मच राइस विनेगर","2 बड़े चम्मच और 2 छोटे चम्मच कम सोडियम वाली सोया सॉस","1 बड़ा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","1 (14 औंस) पैकेट एक्स्ट्रा फ़र्म टोफू"],
["ओवन को पहले से 450°F पर गरम करें। एक बड़ी किनारे वाली बेकिंग शीट पर बिना ब्लीच किया बेकिंग पेपर बिछाएँ।","ज़रूरत हो तो टोफू को थपथपाकर या निचोड़कर अतिरिक्त तरल निकाल दें। टोफू को (3/4 इंच के) टुकड़ों में काटें।","एक बड़े कटोरे में अदरक, तमारी, सिरका और तेल फेंटें। तोरई और शिमला मिर्च के टुकड़े सॉस के मिश्रण में डालें; हाथ से मिलाकर लपेटें।","तोरई और शिमला मिर्च को बेकिंग शीट पर एक परत में सजाएँ (शीट के 2/3 हिस्से में), अतिरिक्त सॉस को कटोरे में वापस टपकने दें।","टोफू को बचे हुए सॉस वाले कटोरे में डालें; मिलाकर लपेटें। टोफू को बेकिंग शीट पर एक परत में सजाएँ (शीट का बाकी हिस्सा भरें)। बचा हुआ सॉस टोफू पर डालें।","टोफू और सब्ज़ियाँ भूरी होने तक, लगभग 30 मिनट भूनें; चलाने की ज़रूरत नहीं। परोसें।"]))
x.append(R(6485584,"हरी मिर्च चिकन कैसरोल","यह हरी मिर्च चिकन कैसरोल सबको पसंद आने वाला व्यंजन है, और हरी मिर्च, चिकन और चीज़ का मेल एक आरामदायक और स्वादिष्ट व्यंजन बनाता है। यह हफ़्ते के किसी दिन के आसान रात के खाने के लिए बिल्कुल सही है जिसका पूरा परिवार आनंद ले सके।","8","लगभग 1/2 कप",
["1 स्प्रे नॉनस्टिक कुकिंग स्प्रे","2 कप पका हुआ चिकन (ब्रेस्ट, कसा हुआ/रेशेदार)","1 (15 औंस) कैन काली बीन्स (बिना नमक मिलाए, धोई और निथारी हुई)","1 (4 औंस) कैन डिब्बाबंद हरी मिर्च (निथारी हुई)","2 मध्यम लाल शिमला मिर्च","1 कप सादा नॉनफैट ग्रीक योगर्ट","1/3 कप सालसा वर्दे (टोमैटिलो सालसा)","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च","3/4 कप कद्दूकस किया मैक्सिकन चीज़ मिश्रण (कम वसा वाला)","1 बड़ा चम्मच ताज़ा धनिया (कटा हुआ, सजावट के लिए)"],
["ओवन को पहले से 375 डिग्री F पर गरम करें। 9 इंच के चौकोर बेकिंग डिश पर कुकिंग स्प्रे करें।","एक बड़े कटोरे में कटा हुआ चिकन, काली बीन्स, कटी हरी मिर्च, लाल शिमला मिर्च, ग्रीक योगर्ट, सालसा वर्दे, पिसा जीरा, लहसुन पाउडर और काली मिर्च मिलाएँ। अच्छी तरह मिलने तक मिलाएँ।","चिकन के मिश्रण को बेकिंग डिश में डालें और बराबर फैलाएँ।","ऊपर से कद्दूकस किया चेडर चीज़ छिड़कें।","कैसरोल को फ़ॉइल से ढककर 25 मिनट बेक करें।","फ़ॉइल हटाएँ और तब तक बेक करें जब तक कैसरोल गरम और बुलबुले वाला न हो जाए और चीज़ पिघलकर सुनहरा भूरा न हो जाए, लगभग 10 मिनट और।","ओवन से निकालें और 8 चौकोर टुकड़ों में काटने से पहले कुछ मिनट ठंडा होने दें। ऊपर से कटा हुआ ताज़ा धनिया डालें।"]))
x.append(R(6486814,"स्मोकी मशरूम","पके हुए मशरूम बर्गर या स्टेक के चटपटे स्वाद को बढ़ाते हैं। ये भुने हुए पोर्क लोइन या ग्रिल किए टोफू के लिए भी बिल्कुल सही साइड डिश हैं। इस रेसिपी में आप सफ़ेद, क्रिमिनी (बेबी बेला), शिटाके या ऑयस्टर मशरूम, या अलग-अलग किस्मों का मिश्रण उपयोग कर सकते हैं। अगर आप शिटाके मशरूम उपयोग कर रहे हैं, तो पूरा डंठल हटाकर फेंक दें।","5","1/2 कप",
["1/2 छोटा चम्मच कोशर नमक","1 बड़ा चम्मच भुना हुआ तिल का तेल","1 1/2 बड़े चम्मच लिक्विड स्मोक","2 1/2 बड़े चम्मच ऑलिव ऑयल","1 1/2 पाउंड सफ़ेद (बटन) मशरूम","1 साबुत बेकिंग पेपर"],
["ओवन को पहले से 350°F पर गरम करें। दो बेकिंग शीट पर बेकिंग पेपर बिछाएँ; एक तरफ रख दें।","सफ़ेद मशरूम के डंठल काट दें। मशरूम को 3/8 इंच मोटे टुकड़ों में काटें। मशरूम को एक कटोरे में डालें। बची हुई सामग्री डालें और अच्छी तरह मिलाएँ। मिश्रण सूखा दिखेगा।","मशरूम को हर शीट पर एक परत में फैलाएँ। 10 मिनट भूनें। मशरूम के स्लाइस पलटें और 10 मिनट और भूनें।","आंच को 375°F तक बढ़ाएँ और 15 मिनट भूनें। मशरूम के स्लाइस फिर पलटें और 10 मिनट और भूनना जारी रखें। साइड डिश के रूप में परोसें, या सैंडविच, ऑमलेट और सूप में डालें।"]))
x.append(R(6487257,"शकरकंद और पालक के डम्पलिंग","चटपटे शकरकंद के डम्पलिंग इस रेस्तराँ-स्तर के मुख्य व्यंजन में मांस वाली टमाटर सॉस से घिरे होते हैं।","8","3 डम्पलिंग, 1/4 कप सॉस",
["1 बड़ा शकरकंद","1 बड़ा अंडा","2 बड़े एग व्हाइट","1 कप फैट-फ्री, कम सोडियम रिकोटा चीज़","2 बड़े चम्मच परमेसन चीज़ (कद्दूकस किया हुआ)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच पिसा जायफल","1/2 कप फ्रोज़न पालक (कटा हुआ, पिघलाया और निथारा हुआ)","1 कप सफ़ेद होल-व्हीट आटा","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पाउंड कम चर्बी वाला टर्की का कीमा (98% फैट-फ्री)","1 मरीनारा सॉस (24.5 औंस का जार, कम सोडियम वाली (जैसे Amy's))","1 कप चिकन या वेजिटेबल ब्रॉथ (कम सोडियम वाला)"],
["ओवन को पहले से 375 डिग्री F पर गरम करें। शकरकंद को बेकिंग शीट पर रखें और 40 मिनट या कांटे से चुभाने पर नरम होने तक बेक करें। शकरकंद को ओवन से निकालें और ठंडा होने के लिए एक तरफ रख दें।","इस बीच, एक बड़े कटोरे में अंडा, एग व्हाइट और कॉटेज चीज़ को चिकना होने तक फेंटें। परमेसन चीज़, काली मिर्च, जायफल और पालक को फोल्ड करके मिलाएँ।","शकरकंद का छिलका उतारें और अच्छी तरह मसलें। मसले शकरकंद और आटे को अंडे-चीज़ के मिश्रण में फोल्ड करें। मिश्रण गीला और चिपचिपा होगा। इसे 10 मिनट रखा रहने दें।","जब तक आटा रखा है, एक बड़े सॉते पैन या डच ओवन पर कुकिंग स्प्रे लगाएँ और मध्यम-तेज़ आंच पर गरम करें। टर्की डालें और बस अंदर तक पकने तक, लगभग 8 मिनट भूनें।","मरीनारा सॉस और ब्रॉथ को टर्की पर डालें और मिलाएँ। आंच को धीमा कर दें।","डम्पलिंग के घोल की 2 इंच की गेंदें निकालें और उन्हें धीरे से सॉस में डालें, ताकि 24 डम्पलिंग बनें। ढककर 20 मिनट हल्की आंच पर पकाएँ।"]))
x.append(R(6487300,"लाल प्याज वाली हरी फलियाँ","बस कुछ मिनट पकाई गई ताज़ी हरी फलियों में हल्का कुरकुरापन और चटकीला स्वाद होता है। ताज़े थाइम और भुने हुए लाल प्याज के साथ यह साइड डिश आपका पसंदीदा बन जाएगा।","8","1 कप",
["1/2 छोटा चम्मच समुद्री नमक","2 पाउंड ताज़ी हरी फलियाँ (छँटी हुई)","5 छोटे चम्मच लाइट बटर जैसा स्प्रेड","2 बड़े चम्मच ऑलिव ऑयल","2 मध्यम लाल प्याज (आधे कटे, छिले और 1/2 इंच मोटे कटे हुए)","1 बड़ा चम्मच ताज़ा थाइम (बारीक कटा हुआ)","1/2 कप कटे हुए बादाम","1 बड़ा चम्मच नींबू का ज़ेस्ट (1 मध्यम नींबू से)"],
["6 क्वार्ट के बर्तन में 2/3 भरकर पानी उबालें। नमक डालें। हरी फलियाँ डालें और आंच बंद कर दें। हरी फलियों को 3 से 4 मिनट पानी में रहने दें। निथार लें। हरी फलियों को बर्फ़ के पानी के कटोरे में डालें। फलियाँ निथारकर एक तरफ रख दें।","एक बड़ी कड़ाही में मध्यम आंच पर बटर स्प्रेड और तेल गरम करें। प्याज डालें और बीच-बीच में चलाते हुए 20 से 25 मिनट तक, बहुत नरम होने तक पकाएँ। अगर प्याज बहुत जल्दी भूरा होने लगे तो आंच कम कर दें।","थाइम और हरी फलियों को प्याज में डालें और गरम होने तक पकाएँ, सब्ज़ियों को चिमटे से धीरे से पलटते हुए। परोसने के लिए प्याज-हरी फलियों के मिश्रण को प्लेटर पर रखें और ऊपर से बादाम और नींबू का ज़ेस्ट डालें।"]))
x.append(R(6488181,"झींगा सेविचे","सेविचे के इस संस्करण में चटपटा झींगा, मीठा अनानास और तीखी मिर्चें खट्टे नींबू के मैरिनेड में हैं। इसे पके हुए चावल और मटर के ऊपर या पकी हुई मछली पर सालसा के रूप में परोसें। या फिर नाश्ते या स्टार्टर के रूप में क्रैकर्स के साथ परोसें।","6","1/2 कप",
["1 बड़ा चम्मच ऑलिव ऑयल","1 छोटा चम्मच लहसुन पाउडर","2 बड़े चम्मच सफ़ेद सिरका","3 बड़े चम्मच नींबू का रस (लाइम)","2 बड़े चम्मच ताज़ा धनिया","1 कप कटा हुआ अनानास","1 छोटी तीखी मिर्च (मोटी कटी हुई)","1 पीली बनाना पेपर मिर्च (मोटी कटी हुई)","1 मध्यम टमाटर (मोटा कटा हुआ)","2 हरे प्याज (मोटे कटे हुए)","12 झींगे (फ्रोज़न, पके हुए और छिले हुए)"],
["मिश्रण को सर्विंग बाउल में रखें और कटा हुआ झींगा और ऑलिव ऑयल डालें। परोसने से पहले 30 मिनट या उससे ज़्यादा ठंडा करें।","फ़ूड प्रोसेसर में हरे प्याज, टमाटर, मिर्चें, अनानास और धनिया डालें; ऑन-ऑफ़ बटन से पल्स करके बहुत मोटा कटने तक पीसें। टुकड़ों वाली बनावट चाहिए। मिश्रण में नींबू का रस, सिरका और लहसुन पाउडर डालें।"]))
x.append(R(6488782,"केल-सेब स्लॉ","आप इस स्लॉ में कटी पालक, हरी पत्तागोभी और कद्दूकस की गाजर का उपयोग करके सब्ज़ियाँ बदल सकते हैं।\n\nअपनी थाली पूरी करें: इस सब्ज़ी वाले साइड डिश को ईज़ी बीफ़ चिली के साथ परोसें। दोनों बचे हुए रूप में भी बढ़िया रहते हैं, इसलिए यह मील-प्रेप के लिए बेहतरीन भोजन है।","4","1 1/4 कप",
["1/2 कप सादा नॉनफैट ग्रीक योगर्ट","1 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच डिजॉन सरसों","1 बड़ा चम्मच ऑलिव ऑयल","3 बड़े चम्मच नींबू का रस","3 बड़े चम्मच पानी","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","2 कप कटा हुआ केल","3 कप कद्दूकस की हुई लाल पत्तागोभी","1 फ़ूजी सेब (छिलके सहित कद्दूकस किया हुआ)"],
["एक बड़े कटोरे में योगर्ट, लहसुन, सरसों, ऑलिव ऑयल, नींबू का रस, पानी, नमक और काली मिर्च फेंटें।","केल, पत्तागोभी और सेब को कटोरे में डालें और बराबर लपेटने के लिए मिलाएँ। ढककर परोसने से 30 मिनट पहले रेफ्रिजरेटर में रखें ताकि स्वाद आपस में मिल जाएँ।"]))
x.append(R(6489390,"लगभग चिकनी सालसा","क्या आप चिकनी सालसा पसंद करते हैं या टुकड़ों वाली? अगर आपको सालसा चिकनी पसंद है, तो चिकना होने तक ब्लेंड करें। अगर आपको टुकड़ों वाली पसंद है, तो ब्लेंड करना बिल्कुल छोड़ दें।","12","2 बड़े चम्मच",
["2 मध्यम रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटे हुए)","1/4 मध्यम हरी शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1/4 मध्यम लाल प्याज (छोटे टुकड़ों में कटा हुआ)","1/2 साबुत जलापेनो मिर्च (बीज और नसें निकाली और छोटे टुकड़ों में कटी हुई)","3 बड़े चम्मच ताज़ा धनिया (कटा हुआ)","1 बड़ा चम्मच नींबू का रस (लाइम)","1 बड़ा चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
["टमाटर, शिमला मिर्च, प्याज, जलापेनो और धनिया को एक मध्यम कटोरे में डालें। नींबू का रस, ऑलिव ऑयल, नमक और काली मिर्च डालें। बराबर लपेटने के लिए मिलाएँ।","इमर्शन ब्लेंडर से लगभग चिकना होने तक ब्लेंड करें, सालसा में कुछ टुकड़े छोड़ते हुए।"]))
x.append(R(6489812,"अजमोद और धनिया चिमिचुरी बेक्ड कॉड","अजमोद, धनिया, सिरके और नींबू से बनी चटपटी चिमिचुरी सॉस हल्के स्वाद वाली कॉड मछली के ऊपर डाली जाती है। यह मधुमेह के अनुकूल प्रोटीन व्यंजन जल्दी बन जाता है और ओवन में बेक करके बनाना आसान है। इसके साथ स्वादिष्ट स्टार्च साइड के रूप में धनिया-नींबू क्विनोआ बनाकर देखें।","4","1 कॉड + 2 बड़े चम्मच सॉस",
["4 (4 औंस) कॉड फ़िलेट","4 कली लहसुन","1/2 मध्यम लाल प्याज (कटा हुआ)","1 कप ताज़ा चपटी पत्ती वाला अजमोद (ठूँस-ठूँसकर भरा हुआ)","1 कप ताज़ी धनिया की पत्तियाँ (ठूँस-ठूँसकर भरी हुई)","1/4 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स","1/8 छोटा चम्मच काली मिर्च","2 बड़े चम्मच रेड वाइन विनेगर","1 छोटा चम्मच नींबू का ज़ेस्ट (लाइम)","2 बड़े चम्मच ताज़ा नींबू का रस (लाइम)","4 बड़े चम्मच ऑलिव ऑयल (बाँटकर उपयोग के लिए)"],
["ओवन को पहले से 400°F पर गरम करें।","कॉड फ़िलेट को बेकिंग पेपर बिछी बेकिंग शीट पर रखें। ऊपर से 1 बड़ा चम्मच तेल हल्के से डालें। बेकिंग शीट को ओवन में रखें और तब तक पकाएँ जब तक मछली का आंतरिक तापमान 145°F न हो जाए, 8–10 मिनट।","लहसुन, प्याज, अजमोद, धनिया, कुटी लाल मिर्च और काली मिर्च को फ़ूड प्रोसेसर में डालें। बारीक कटने तक प्रोसेस करें।","सिरका, नींबू का ज़ेस्ट और रस, और 3 बड़े चम्मच ऑलिव ऑयल डालें। चिकना होने तक प्रोसेस करें और एक तरफ रख दें।","परोसने के लिए, मछली को प्लेटों में बाँटें और ऊपर से चिमिचुरी सॉस डालें।"]))
